  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases phase1Limit - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken { break; }
  generated := generated + [next];
  if RenderedEndsWith(generated, "<<") {
    var eg, ei, ec := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg; insideConstrainedOut := ei; currentConstrainedOut := ec;
  }
}

// Phase 5: Constrained loop for span from Phase 4 (max 10 tokens)
var innerSteps2: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps2 < innerStepLimit
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerStepLimit - innerSteps2
{
  var cg2, ci2, cc2, closed2 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed2 {
    generated := cg2; insideConstrainedOut := ci2; currentConstrainedOut := cc2;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    var cp2 := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next2 := helpers.ConstrainedStep(lm, parser, cp2, currentConstrainedOut, eosToken);
    steps := steps + 1; innerSteps2 := innerSteps2 + 1;
    if next2 == eosToken { break; }
    var ag2, ai2, ac2 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next2);
    generated := ag2; insideConstrainedOut := ai2; currentConstrainedOut := ac2;
  }
}

// Phase 6: Force close with ALL remaining budget
if insideConstrainedOut && steps < maxSteps {
  var bud2 := maxSteps - steps;
  var wg2, wi2, wc2 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud2);
  generated := wg2; insideConstrainedOut := wi2; currentConstrainedOut := wc2;
  steps := steps + bud2;
  if !insideConstrainedOut { hasCompletedSpan := true; }
}

// Phase 7: Force open a span if nothing completed yet
if !insideConstrainedOut && !hasCompletedSpan && steps + 2 <= maxSteps {
  var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg; insideConstrainedOut := fi; currentConstrainedOut := fc;
  steps := steps + 1;

  var innerSteps3: nat := 0;
  var innerLimit3: nat := 10;
  while insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && innerSteps3 < innerLimit3
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps + innerLimit3 - innerSteps3
  {
    var cg3, ci3, cc3, closed3 := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed3 {
      generated := cg3; insideConstrainedOut := ci3; currentConstrainedOut := cc3;
      steps := steps + 1;
      hasCompletedSpan := true;
    } else {
      var cp3 := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next3 := helpers.ConstrainedStep(lm, parser, cp3, currentConstrainedOut, eosToken);
      steps := steps + 1; innerSteps3 := innerSteps3 + 1;
      if next3 == eosToken { break; }
      var ag3, ai3, ac3 := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next3);
      generated := ag3; insideConstrainedOut := ai3; currentConstrainedOut := ac3;
    }
  }

  if insideConstrainedOut && steps < maxSteps {
    var bud3 := maxSteps - steps;
    var wg3, wi3, wc3 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud3);
    generated := wg3; insideConstrainedOut := wi3; currentConstrainedOut := wc3;
    steps := steps + bud3;
  }
}

// Phase 8: Final safety close with all remaining budget
if insideConstrainedOut && steps < maxSteps {
  var bud4 := maxSteps - steps;
  if bud4 > 0 {
    var wg4, wi4, wc4 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud4);
    generated := wg4; insideConstrainedOut := wi4; currentConstrainedOut := wc4;
    steps := steps + bud4;
  }
}

cost := steps;
